import{_ as e,o as t,c as o,a5 as a}from"./chunks/framework.CXroN2RO.js";const c="/study/images/network/udp-datagrams.svg",p=JSON.parse('{"title":"UDPデータグラムの境界と送受信","description":"","frontmatter":{"title":"UDPデータグラムの境界と送受信","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"network","summary":"UDPがメッセージを渡す単位を追い、Winsockでの送信元、受信バッファ不足、空のデータグラムを説明する。経路MTU、輻輳制御、ゲームの状態更新にもつなげる。","aliases":["UDP","datagram","データグラム","sendto","recvfrom","WSAEMSGSIZE","path MTU","PMTU","IPフラグメント","QUIC"],"verification":"IETFのUDP関連RFCとMicrosoftのWinsock仕様に照合（2026-11-07）"}},"headers":[],"relativePath":"network/udp-datagrams.md","filePath":"network/udp-datagrams.md"}'),n={name:"network/udp-datagrams.md"};function d(s,r,f,i,l,h){return t(),o("div",null,[...r[0]||(r[0]=[a('<h1 id="udpデータグラムの境界と送受信" tabindex="-1">UDPデータグラムの境界と送受信 <a class="header-anchor" href="#udpデータグラムの境界と送受信" aria-label="Permalink to &quot;UDPデータグラムの境界と送受信&quot;">​</a></h1><p>UDPでは、一件のメッセージを<strong>データグラム</strong>として送ります。例えば位置の更新を二件送ると、受信側は届いたデータグラムを一件ずつ取り出せます。届くか、送信順に並ぶか、同じものが複数届くかは、UDPの外で扱う必要があります。TCPで順序のあるバイト列を読む場合は、アプリが長さなどからメッセージの境界を復元します。<a href="https://www.rfc-editor.org/rfc/rfc768.html" target="_blank" rel="noreferrer">IETF RFC 768</a> · <a href="/study/network/tcp-sockets.html">TCPのメッセージ境界</a></p><h2 id="送信元・宛先とデータグラムの長さ" tabindex="-1">送信元・宛先とデータグラムの長さ <a class="header-anchor" href="#送信元・宛先とデータグラムの長さ" aria-label="Permalink to &quot;送信元・宛先とデータグラムの長さ&quot;">​</a></h2><p>UDPはIPの上で動きます。IPヘッダーに送信元と宛先のIPアドレスがあり、8バイトのUDPヘッダーに送信元ポート、宛先ポート、長さ、チェックサムがあります。通常のUDPの長さ欄はヘッダーとペイロードの合計です。ペイロードが空なら、長さ欄は<code>8</code>です。<a href="https://www.rfc-editor.org/rfc/rfc768.html" target="_blank" rel="noreferrer">IETF RFC 768のヘッダー形式</a></p><p>Winsockでは<code>SOCK_DGRAM</code>のソケットを使います。受信側は<code>bind</code>でローカルのアドレスとポートを割り当てます。<code>sendto</code>は宛先を渡して送信し、<code>recvfrom</code>は受信データに加えて、そのデータグラムの送信元アドレスとポートを返せます。実践では<code>127.0.0.1</code>とポート<code>0</code>で受信側をバインドし、<code>getsockname</code>で取得した実際のポートを宛先に使います。<code>sendto</code>が成功を返した段階で確認できるのは、ローカルの送信処理がデータを受け付けたことまでです。<a href="https://learn.microsoft.com/en-us/windows/win32/api/winsock2/nf-winsock2-bind" target="_blank" rel="noreferrer">Microsoftのbind</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/winsock2/nf-winsock2-sendto" target="_blank" rel="noreferrer">sendto</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/winsock/nf-winsock-recvfrom" target="_blank" rel="noreferrer">recvfrom</a></p><p>相手が一つなら、WinsockのUDPソケットにも<code>connect</code>で相手を設定できます。設定後は<code>send</code>で既定の宛先へ送り、<code>recv</code>でその相手からのデータグラムを受け取れます。この操作はローカルソケットの設定であり、相手とのハンドシェイクを伴いません。相手が応答したことを確認したい場合は、アプリの要求と応答を照合します。<a href="https://learn.microsoft.com/en-us/windows/win32/api/winsock2/nf-winsock2-connect" target="_blank" rel="noreferrer">Microsoftのconnect</a> · <a href="https://www.rfc-editor.org/rfc/rfc8085.html#section-5" target="_blank" rel="noreferrer">IETF RFC 8085 §5</a></p><h2 id="受信バッファが短い場合と、長さ0の場合" tabindex="-1">受信バッファが短い場合と、長さ0の場合 <a class="header-anchor" href="#受信バッファが短い場合と、長さ0の場合" aria-label="Permalink to &quot;受信バッファが短い場合と、長さ0の場合&quot;">​</a></h2><p>以下は、フラグ<code>0</code>を渡し、正の長さの受信バッファを使うWindowsの<code>recvfrom</code>の結果です。成功時の戻り値はペイロードのバイト数です。エラー時は<code>SOCKET_ERROR</code>を返すので、その場で<code>WSAGetLastError</code>を呼びます。<a href="https://learn.microsoft.com/en-us/windows/win32/api/winsock/nf-winsock-recvfrom" target="_blank" rel="noreferrer">Microsoftのrecvfrom</a></p><figure class="study-figure"><img src="'+c+'" alt="WindowsのUDP受信例。小さなデータグラムAとBは、それぞれ別のrecvfromで受け取る。8バイトを4バイトのバッファで受けると、先頭4バイトが入り、残りは失われてWSAEMSGSIZEになる。空のデータグラムを受けると0が返る。" width="760" height="410" loading="lazy"><figcaption>キューの先頭にあるデータグラムを一件ずつ取り出します。<a href="/study/images/network/udp-datagrams.svg" target="_blank" rel="noopener noreferrer">UDPの受信例を拡大</a></figcaption></figure><table tabindex="0"><thead><tr><th>受信時の状況</th><th>Windowsの<code>recvfrom</code>の結果</th></tr></thead><tbody><tr><td>バッファに収まるAとBがこの順で受信キューに入った</td><td>一回目にA、次の呼び出しでBを受け取ります。</td></tr><tr><td>8バイトのデータグラムに4バイトのバッファを渡した</td><td>先頭4バイトをバッファに入れ、<code>WSAEMSGSIZE</code>で失敗します。残り4バイトは失われます。</td></tr><tr><td>長さ0のデータグラムが届いた</td><td><code>0</code>を返します。空のメッセージを一件受け取った結果で、次のデータグラムも同じソケットで受信できます。</td></tr><tr><td>キューが空で、ソケットが非ブロッキングに設定されている</td><td><code>WSAEWOULDBLOCK</code>で失敗します。</td></tr></tbody></table><p><code>WSAEMSGSIZE</code>のあとの受信は次のデータグラムを対象にします。切り詰められたデータは、完全なメッセージとして処理する前に破棄します。一回の<code>recvfrom</code>に渡すバッファは、OS側のソケットの受信キューとは別です。キューが処理しきれない速度で受信すると、アプリが読む前にデータグラムを失うこともあります。<a href="https://learn.microsoft.com/en-us/windows/win32/api/winsock/nf-winsock-recvfrom" target="_blank" rel="noreferrer">Microsoftのrecvfrom</a> · <a href="https://www.rfc-editor.org/rfc/rfc8085.html#section-5" target="_blank" rel="noreferrer">IETF RFC 8085 §5</a></p><h2 id="経路のmtuと、送る速さを考える" tabindex="-1">経路のMTUと、送る速さを考える <a class="header-anchor" href="#経路のmtuと、送る速さを考える" aria-label="Permalink to &quot;経路のMTUと、送る速さを考える&quot;">​</a></h2><p>経路MTU（PMTU）は、宛先までの経路を分割せずに通れるIPパケットの上限です。UDPペイロードに使える長さは、そこからIPヘッダーとUDPヘッダーを引いて求めます。例えばPMTUが1,500バイトで、IPv4ヘッダーにオプションがなければ<code>1500 − 20 − 8 = 1472</code>バイト、IPv6で拡張ヘッダーがなければ<code>1500 − 40 − 8 = 1452</code>バイトです。トンネルやヘッダーの追加で、使える長さは変わります。<a href="https://www.rfc-editor.org/rfc/rfc8085.html#section-3.2" target="_blank" rel="noreferrer">IETF RFC 8085 §3.2</a> · <a href="https://www.rfc-editor.org/rfc/rfc8200.html#section-3" target="_blank" rel="noreferrer">IETF RFC 8200 §3</a></p><p>IPがパケットを複数のフラグメントに分ける場合、受信側は断片をすべて集めて再構成してからUDPへ渡します。一つの断片を失うと元のデータグラムを受け取れません。IPv6でフラグメントを作るのは送信元です。大きさを調べながら送る方式には、アプリやトランスポートが応答を確認できる探査データグラムを使うDPLPMTUDがあります。<a href="https://www.rfc-editor.org/rfc/rfc8085.html#section-3.2" target="_blank" rel="noreferrer">IETF RFC 8085 §3.2</a> · <a href="https://www.rfc-editor.org/rfc/rfc8200.html#section-4.5" target="_blank" rel="noreferrer">IETF RFC 8200 §4.5</a> · <a href="https://www.rfc-editor.org/rfc/rfc8899.html" target="_blank" rel="noreferrer">IETF RFC 8899</a></p><p>UDPを直接使うインターネット通信では、アプリか上位プロトコルで輻輳に応じて送信を調整します。例えば送信を短時間に集中させず、受信側からのフィードバックで混雑を検知したら送る量や頻度を落とします。送信量が経路上のボトルネックを超えると、キューの待ち時間が増え、容量を使い切ると損失も起きます。<a href="https://www.rfc-editor.org/rfc/rfc8085.html#section-3.1" target="_blank" rel="noreferrer">IETF RFC 8085 §3.1</a> · <a href="/study/network/latency-throughput-and-queues.html">遅延・スループットと待ち行列</a></p><h2 id="ゲームのデータごとに期限と順序を決める" tabindex="-1">ゲームのデータごとに期限と順序を決める <a class="header-anchor" href="#ゲームのデータごとに期限と順序を決める" aria-label="Permalink to &quot;ゲームのデータごとに期限と順序を決める&quot;">​</a></h2><p>例えば毎回全体を送る状態スナップショットなら、更新番号<code>100 → 102 → 101</code>の順に届いたとき、<code>102</code>を採用したあとの<code>101</code>を捨てる設計ができます。番号の比較は同じセッションや同じ状態系列の中で行い、有限の番号が一周する場合の比較規則も決めます。古いデータが届くまで進行を止める必要があるかは、状態の置き換え方で変わります。<a href="https://www.rfc-editor.org/rfc/rfc8085.html#section-3.3" target="_blank" rel="noreferrer">IETF RFC 8085 §3.3</a></p><p>一度だけ適用する操作なら、識別子を付け、受信側で重複を検査します。応答がなければ再試行する設計では、再試行の期限と頻度、応答が何を確認したかも定義します。必要な順序や配送の性質に合うトランスポートを選ぶ方法もあります。例えばQUICはUDP上で暗号化された接続を確立し、順序のある信頼性付きストリームと輻輳制御を提供します。拡張を使うと、同じ接続上で再送されないデータグラムも扱えます。<a href="https://www.rfc-editor.org/rfc/rfc9000.html" target="_blank" rel="noreferrer">IETF RFC 9000</a> · <a href="https://www.rfc-editor.org/rfc/rfc9221.html" target="_blank" rel="noreferrer">IETF RFC 9221</a></p><p>実践ではWindowsのIPv4ループバックで、二件の境界、受信バッファ不足、空のデータグラムに続く通常の受信を観察します。<a href="/study/practice/network/udp-loopback-observation.html">C++でUDPの受信結果を確かめる</a></p>',19)])])}const m=e(n,[["render",d]]);export{p as __pageData,m as default};
